window.SCHOOL_LISTENING={"../assets/media/782fa5de91b03488cc8092ca2233806402e311ad70445e53ce867ed41069aab8.mp3":[{"id":"PPT_782fa5de91b03488","audioId":"PPT_782fa5de91b03488","title":"Book 3 · Unit 5 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 92","duration":241.45,"cues":[{"start":0,"end":1.62,"text":"five .six","coverage":1},{"start":1.62,"end":4.98,"text":"Do you have problems focusing on your work?","coverage":1},{"start":5.58,"end":7.16,"text":"Are you under a lot of stress?","coverage":1},{"start":8.06,"end":12.38,"text":"Do you want to get more exercise while trying something new and exciting?","coverage":1},{"start":13.04,"end":15.92,"text":"If so, it's time to take up taekwondo.","coverage":1},{"start":16.46,"end":22.04,"text":"Taekwondo is great exercise and as we all know exercise is good for your health.","coverage":1},{"start":22.74,"end":25.34,"text":"Taekwondo also has mental benefits.","coverage":1},{"start":25.76,"end":28.66,"text":"It has been shown to improve your concentration.","coverage":1},{"start":28.66,"end":30.12,"text":"In addition,","coverage":1},{"start":30.48,"end":32.62,"text":"it makes you feel good about yourself.","coverage":1},{"start":33.7,"end":38.78,"text":"This martial art was developed in Korea and is now popular around the world.","coverage":1},{"start":39.56,"end":41.82,"text":"Whether you are looking for physical well -being,","coverage":1},{"start":42.5,"end":45.46,"text":"increased confidence or a life with less stress,","coverage":1},{"start":45.92,"end":47.9,"text":"Black Belt Taekwondo has it all.","coverage":1},{"start":48.44,"end":53.66,"text":"Sign up now for a free introductory class starting on January the 15th.","coverage":1},{"start":54.52,"end":59.08,"text":"Would you like to improve your social life,","coverage":1},{"start":59.48,"end":60.94,"text":"your intellectual performance,","coverage":1},{"start":61.48,"end":64.82,"text":"your physical fitness and your team building skills?","coverage":1},{"start":65.86,"end":70.92,"text":"Scientific research has proven that team sports offer all of these benefits.","coverage":1},{"start":71.8,"end":75.9,"text":"Join us and take advantage of the many benefits of team sports.","coverage":1},{"start":76.7,"end":83.64,"text":"We're a group of energetic adults of all ages who get together on Sunday afternoons to play football.","coverage":1},{"start":83.64,"end":88.22,"text":"And we're always looking for new players to join in the fun.","coverage":1},{"start":89.54,"end":93.98,"text":"Whether you've been playing football for years or want to take up a new sport,","coverage":1},{"start":94.58,"end":95.94,"text":"you're welcome to participate.","coverage":1},{"start":97.38,"end":98.44,"text":"Everyone can play.","coverage":1},{"start":98.8,"end":100.7,"text":"You don't even need to try out.","coverage":1},{"start":101.64,"end":104.3,"text":"If you're interested in learning more about our group,","coverage":1},{"start":104.74,"end":106.42,"text":"check out our website at","coverage":1},{"start":109.18,"end":110.46,"text":"www .footballsundays","coverage":1},{"start":110.46,"end":111.76,"text":".cup","coverage":1},{"start":111.76,"end":113.02,"text":".com","coverage":1},{"start":113.64,"end":118.64,"text":"Sign up today and you can be part of a team as early as this weekend.","coverage":1},{"start":119.56,"end":121.76,"text":"Hope to see you on the field soon.","coverage":1},{"start":124.62,"end":125.12,"text":"Hi,","coverage":1},{"start":125.48,"end":129.68,"text":"my name's Angie Stratton and I'm the director of Culture Cycle.","coverage":1},{"start":130.54,"end":133.26,"text":"Culture Cycle is a new concept in travel,","coverage":1},{"start":134.08,"end":135.78,"text":"educational fitness touring.","coverage":1},{"start":136.98,"end":143.04,"text":"We offer courses all over the world which combine learning with exercise and travel.","coverage":1},{"start":143.64,"end":150.48,"text":"Each course has an educational theme such as Brazilian cooking or the history of Turkey.","coverage":1},{"start":151.44,"end":152.46,"text":"As a small group,","coverage":1},{"start":152.98,"end":155.08,"text":"we cycle from place to place,","coverage":1},{"start":155.42,"end":158.9,"text":"stopping for several days in each location to rest,","coverage":1},{"start":159.36,"end":162.26,"text":"relax and do some hands -on learning.","coverage":1},{"start":163.24,"end":169.34,"text":"Not only does this trip provide terrific exercise and a fascinating cultural experience,","coverage":1},{"start":169.68,"end":171.5,"text":"it's the best way to learn.","coverage":1},{"start":172.16,"end":172.58,"text":"There's","coverage":1},{"start":172.58,"end":173,"text":"no","coverage":1},{"start":173,"end":178.12,"text":"question that physical activity improves our memory and thinking skills.","coverage":1},{"start":178.72,"end":181.08,"text":"So, after a few days of cycling,","coverage":1},{"start":181.7,"end":184.02,"text":"your brain will be ready to learn.","coverage":1},{"start":184.76,"end":193.32,"text":"So, be kind to your body and your mind and come with us on an amazing adventure you'll never forget.","coverage":1},{"start":195.78,"end":198.54,"text":"Are you interested in alternative treatments?","coverage":1},{"start":199.14,"end":203.88,"text":"Have you ever wanted to explore the secrets of traditional Chinese medicine?","coverage":1},{"start":204.96,"end":208.88,"text":"This spring, join our six -month course in acupuncture,","coverage":1},{"start":209.6,"end":215.94,"text":"a treatment for pain or illness which involves putting needles under the skin at special points on the body.","coverage":1},{"start":216.7,"end":222.08,"text":"The course covers the theory of acupuncture and practical skills in using needles.","coverage":1},{"start":223.16,"end":225.38,"text":"Acupuncture is known to reduce pain,","coverage":1},{"start":226.08,"end":231.82,"text":"but it's also a great alternative for people who want to lose weight in an easy way.","coverage":1},{"start":232.62,"end":239.48,"text":"Learn more about the course and visit us on our Open House Days on the first Saturday of every month.","coverage":1}],"file":"03d907e01ecf289fb835.js","track":0,"media":"../assets/media/782fa5de91b03488cc8092ca2233806402e311ad70445e53ce867ed41069aab8.mp3"}],"../assets/media/bb41ebac44f4df5e7f357aea7026df07c6f452e048e2ae8b05f56b4d5a564bf2.mp3":[{"id":"PPT_bb41ebac44f4df5e","audioId":"PPT_bb41ebac44f4df5e","title":"Book 3 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 60","duration":33.07,"cues":[{"start":0,"end":2.24,"text":"five .five","coverage":1},{"start":2.24,"end":5.7,"text":"one I think it's great news!","coverage":1},{"start":8.06,"end":10.4,"text":"two Oh, that's great!","coverage":1},{"start":12.4,"end":13.36,"text":"three","coverage":1},{"start":13.98,"end":15.88,"text":"What's wrong with being healthy?","coverage":1},{"start":17.7,"end":18.66,"text":"four","coverage":1},{"start":19.24,"end":24.04,"text":"So now we should all eat fast food and stop exercising?","coverage":1},{"start":26,"end":26.96,"text":"five","coverage":1},{"start":27.92,"end":31.14,"text":"I'd say that it's always better to have a healthy lifestyle","coverage":1}],"file":"3cc05f5161d8f7aae668.js","track":0,"media":"../assets/media/bb41ebac44f4df5e7f357aea7026df07c6f452e048e2ae8b05f56b4d5a564bf2.mp3"}],"../assets/media/b8632be10dde55d72d6e5b910f089156fcf9cac79d718a0a83d2658bfeabd66f.mp3":[{"id":"PPT_b8632be10dde55d7","audioId":"PPT_b8632be10dde55d7","title":"Book 3 · Unit 5 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 228","duration":41.77,"cues":[{"start":0,"end":1.76,"text":"Unit five,","coverage":1},{"start":2.3,"end":3.74,"text":"five .one","coverage":1},{"start":3.74,"end":7.86,"text":"Today we're talking about the key to a long and happy life.","coverage":1},{"start":8.54,"end":15.98,"text":"Recent studies of people who live to be a hundred years old have shown that a healthy diet and exercise may not be enough.","coverage":1},{"start":16.58,"end":24.62,"text":"In fact many of the people who celebrate their hundreds birthday have not eaten a healthy diet and have never exercised regularly.","coverage":1},{"start":25.38,"end":29.94,"text":"This has led many people to believe that our lifestyles are not important.","coverage":1},{"start":30.54,"end":33.58,"text":"What's most important is that we have good genes.","coverage":1},{"start":34.28,"end":39.86,"text":"It seems that if you have the right genes then you'll live for a long time whatever you do.","coverage":1}],"file":"8bde007efb7b78fae97f.js","track":0,"media":"../assets/media/b8632be10dde55d72d6e5b910f089156fcf9cac79d718a0a83d2658bfeabd66f.mp3"}],"../assets/media/93af01949e3ad24fa576dd8e26c317a356ab5550ba1ebba9790ad4689d231952.mp3":[{"id":"PPT_93af01949e3ad24f","audioId":"PPT_93af01949e3ad24f","title":"Book 3 · Unit 5 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 239","duration":16.09,"cues":[{"start":0,"end":1.7,"text":"five .three","coverage":1},{"start":1.7,"end":4.48,"text":"I'm really surprised about that.","coverage":1}],"file":"bb62f5a783a31729e347.js","track":0,"media":"../assets/media/93af01949e3ad24fa576dd8e26c317a356ab5550ba1ebba9790ad4689d231952.mp3"}],"../assets/media/fc7a0b7e619332e88744250f9a73a6b266cc67564a77637d0d649bedc591046f.mp3":[{"id":"PPT_fc7a0b7e619332e8","audioId":"PPT_fc7a0b7e619332e8","title":"Book 3 · Unit 5 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 242","duration":42.32,"cues":[{"start":0,"end":2.22,"text":"five .four","coverage":1},{"start":3.3,"end":6.76,"text":"one I'm really happy about this new research.","coverage":1},{"start":9.1,"end":10.02,"text":"two","coverage":1},{"start":10.76,"end":11.48,"text":"There's","coverage":1},{"start":11.48,"end":11.8,"text":"no","coverage":1},{"start":11.8,"end":14.26,"text":"question that happy people live longer.","coverage":1},{"start":16.74,"end":17.54,"text":"three","coverage":1},{"start":18.4,"end":23.64,"text":"It's ridiculous to get too worried about healthy eating and exercise.","coverage":1},{"start":25.94,"end":26.86,"text":"four","coverage":1},{"start":28.2,"end":31.42,"text":"He certainly never went to a gym.","coverage":1},{"start":34.44,"end":34.46,"text":"five","coverage":1},{"start":35.44,"end":36.08,"text":"There's","coverage":1},{"start":36.08,"end":36.38,"text":"no","coverage":1},{"start":36.38,"end":40.36,"text":"doubt that bad health habits increase the chances of getting a serious illness.","coverage":1}],"file":"be8a3fa3bfc3bb9fa32b.js","track":0,"media":"../assets/media/fc7a0b7e619332e88744250f9a73a6b266cc67564a77637d0d649bedc591046f.mp3"}],"../assets/media/06fbfee20dd35b6c663b68a1cdeef537adf55b863826bef206976f19ef9e9ab8.mp3":[{"id":"PPT_06fbfee20dd35b6c","audioId":"PPT_06fbfee20dd35b6c","title":"Book 3 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 43","duration":176.67,"cues":[{"start":0,"end":1,"text":"five .two","coverage":1},{"start":1.98,"end":2.64,"text":"So,","coverage":1},{"start":3.02,"end":9.34,"text":"new research shows that having a healthy lifestyle is not the most important thing if you want to live a long life.","coverage":1},{"start":9.84,"end":14.08,"text":"We asked four people on the street for their reactions to this news.","coverage":1},{"start":14.82,"end":16.36,"text":"I think it's great news.","coverage":1},{"start":16.96,"end":22.04,"text":"Most people think that if they eat healthy food and exercise a lot they'll live forever.","coverage":1},{"start":22.76,"end":26.24,"text":"These people never drink coffee or sugary drinks.","coverage":1},{"start":26.64,"end":34,"text":"They spend hours working out in the gym or doing yoga and none of this matters if you have the wrong genes.","coverage":1},{"start":34.76,"end":38.4,"text":"I think that the key to a healthy life is to enjoy yourself.","coverage":1},{"start":38.86,"end":42.84,"text":"If you focus all your energy on what to do and what not to do,","coverage":1},{"start":43.28,"end":44.82,"text":"you'll be unhappy eventually.","coverage":1},{"start":45.38,"end":45.6,"text":"There's","coverage":1},{"start":45.6,"end":45.88,"text":"no","coverage":1},{"start":45.88,"end":48.36,"text":"question that happy people live longer.","coverage":1},{"start":49.18,"end":53.74,"text":"I'd much rather go out and have a pizza with friends than spend time in the gym.","coverage":1},{"start":54.36,"end":56.46,"text":"I'm really happy about this new research.","coverage":1},{"start":58.38,"end":61.9,"text":"This research proves what I've known for a long time.","coverage":1},{"start":62.38,"end":67.12,"text":"It's ridiculous to get too worried about healthy eating and exercise.","coverage":1},{"start":67.78,"end":73.74,"text":"My grandfather lived until he was 95 even though he never exercised.","coverage":1},{"start":74.2,"end":77.94,"text":"He ate lots of sugar and never ate vegetables.","coverage":1},{"start":78.68,"end":80.92,"text":"He was brought up in a different world.","coverage":1},{"start":81.44,"end":82.98,"text":"He had different habits.","coverage":1},{"start":83.42,"end":85.64,"text":"He certainly never went to a gym.","coverage":1},{"start":86.46,"end":90.52,"text":"Yes, I'm sure that genes are more important than our lifestyle.","coverage":1},{"start":91.32,"end":97.1,"text":"Of course, I'm not going to give up exercising or start eating fast food every day.","coverage":1},{"start":97.64,"end":105.64,"text":"The research shows I should stay in shape because it makes me feel better but I won't allow fitness to take over my whole life.","coverage":1},{"start":105.64,"end":110.3,"text":"Well, first of all, I prefer to exercise and eat well.","coverage":1},{"start":110.94,"end":112.68,"text":"What's wrong with being healthy?","coverage":1},{"start":113.36,"end":118.4,"text":"I also think that you won't know whether or not you have the right genes until you get sick.","coverage":1},{"start":119.02,"end":121.64,"text":"So why take the risk and be unhealthy?","coverage":1},{"start":122.64,"end":130.06,"text":"Also, don't forget that you might get the flu or a cold much more easily when you don't eat healthy food or exercise.","coverage":1},{"start":130.88,"end":134.72,"text":"I'd say that it's always better to have a healthy lifestyle.","coverage":1},{"start":135.8,"end":136,"text":"There's","coverage":1},{"start":136,"end":136.26,"text":"no","coverage":1},{"start":136.26,"end":140.28,"text":"doubt that bad health habits increase the chances of getting a serious illness.","coverage":1},{"start":140.74,"end":141.76,"text":"Oh, that's great.","coverage":1},{"start":142.12,"end":145.4,"text":"So now we should all eat fast food and stop exercising?","coverage":1},{"start":146.36,"end":150.12,"text":"I mean, I look around and I see overweight children everywhere.","coverage":1},{"start":150.78,"end":150.84,"text":"No","coverage":1},{"start":150.84,"end":159.62,"text":"matter how good their genes are, I'm sure that these children won't be able to enjoy a long and healthy life unless they give up crisps,","coverage":1},{"start":160.02,"end":160.66,"text":"chocolate bars,","coverage":1},{"start":161.18,"end":161.98,"text":"sugary drinks.","coverage":1},{"start":162.8,"end":174.66,"text":"Well it's great that some people can live to be a hundred and do whatever they want in their lives but I prefer to be careful and take care of myself because I don't know if I have good genes.","coverage":1}],"file":"d5c45894aeaadc9ac912.js","track":0,"media":"../assets/media/06fbfee20dd35b6c663b68a1cdeef537adf55b863826bef206976f19ef9e9ab8.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 What activities do you do to stay healthy? Do you have any unhealthy habits that you would like to stop?Possible answer: I walk after class and play basketball at weekends. I would like to stop staying up so late.","slide":4,"shape":"16","bookPage":"104"},{"text":"2 In what ways can technology help us to stay healthy?Possible answer: A fitness tracker can record activity, and an app can remind me to take a break.","slide":4,"shape":"17","bookPage":"104"},{"text":"1 What are the people doing in photos 2 and 4? Why are they doing this?Possible answer: A person is exercising while another records the activity; a woman is sleeping with a phone nearby.","slide":6,"shape":"29","bookPage":"104"},{"text":"2 How might photos 1 and 3 be connected in terms of people's health?Possible answer: One photo shows a brain and the other shows food. Diet may affect brain health.","slide":6,"shape":"30","bookPage":"104"},{"text":"3 What do you think this video will tell you about health?Possible answer: The video may explain how exercise, food, sleep and technology are connected with brain health.","slide":6,"shape":"31","bookPage":"104"},{"text":"1  A neuron carries information in the brain.","slide":14,"shape":"8","bookPage":"104"},{"text":"2  Eggs contain protein.","slide":14,"shape":"9","bookPage":"104"},{"text":"3  Can you interpret the meaning of this message?","slide":14,"shape":"10","bookPage":"104"},{"text":"4  She stayed focused on one task.","slide":14,"shape":"11","bookPage":"104"},{"text":"5  The device sends a signal.","slide":14,"shape":"12","bookPage":"104"},{"text":"6  The team worked effectively and finished on time.","slide":14,"shape":"13","bookPage":"104"},{"text":"3 How technology can help to maintain a training plan.","slide":17,"shape":"6","bookPage":"105"},{"text":"5 The importance of sleep in keeping your brain healthy.","slide":17,"shape":"7","bookPage":"105"},{"text":"4 The benefits that certain types of foods produce in our minds.","slide":17,"shape":"8","bookPage":"105"},{"text":"1 What happens in the brain when we learn or exercise.","slide":17,"shape":"9","bookPage":"105"},{"text":"2 The effects that different types of exercise have on the brain.","slide":17,"shape":"10","bookPage":"105"},{"text":"6 Where technology can help to improve sleep and learning.","slide":17,"shape":"11","bookPage":"105"},{"text":"1 Doing physical exercise encourages the proteins in the brain to grow.Correction: Doing physical exercise encourages the neurons in the brain to grow.","slide":20,"shape":"18","bookPage":"105"},{"text":"2 Aerobic exercise, like running, is best for helping the brain to stay focused.Correction: Resistance training, like lifting weights, helps the brain to stay focused.","slide":20,"shape":"19","bookPage":"105"},{"text":"3 Foods with lots of fat and sugar tend to encourage neuron growth.Correction: Foods with lots of fat and sugar tend to prevent neuron growth.","slide":20,"shape":"20","bookPage":"105"},{"text":"4 Nuts contain fatty acids which are particularly good for old people's brains.Correction: Nuts contain fatty acids which are particularly good for young people's brains.","slide":20,"shape":"5","bookPage":"105"},{"text":"5 People tend to work less effectively when they are feeling confused.Correction: People tend to work less effectively when they are feeling tired.","slide":21,"shape":"19","bookPage":"105"},{"text":"6 Research shows that getting a good night's sleep makes it easier to use smart devices successfully.Correction: Research shows that getting a good night's sleep makes it easier to learn new skills and remember information.","slide":21,"shape":"20","bookPage":"105"},{"text":"1 Of the activities shown in the video, which do you think are the most and least effective in helping to stay healthy?For me, getting enough sleep is especially useful because I find it easier to concentrate afterwards. A tracker alone would help less if I did not change my habits.","slide":23,"shape":"13","bookPage":"105"},{"text":"2 What other activities can somebody do to improve the health of their brain?I would suggest learning a new skill or doing puzzles because these make me think in new ways.","slide":23,"shape":"14","bookPage":"105"},{"text":"3 How is the way we use our brains today different from in the past?We may use maps and remember phone numbers less because our phones do this for us. We also use new skills to find and evaluate information online.","slide":24,"shape":"16","bookPage":"105"},{"text":"7  I'm a few kilos overweight. I should probably eat less fast food.","slide":36,"shape":"6","bookPage":"106"},{"text":"8  The best way to stay in shape is to eat a good diet and do exercise.","slide":36,"shape":"7","bookPage":"106"},{"text":"1 What are the differences between the health and the lifestyles of the people in the photos?Possible answer: Photos a and c contrast food choices; photos b and d contrast being active and sitting down.","slide":39,"shape":"20","bookPage":"106"},{"text":"2 In what ways can lifestyles like the ones shown in the photos affect people's health?Possible answer: Eating habits and activity are two aspects of lifestyle that may affect health.","slide":39,"shape":"21","bookPage":"106"},{"text":"3 Do you think that the genes we receive from our parents can affect our health? How?Possible answer: Genes inherited from parents may influence health. Lifestyle is another possible influence.","slide":40,"shape":"20","bookPage":"106"},{"text":"1 Do people living to 100 always have a healthy lifestyle? No. Some people who reach 100 have not eaten a healthy diet and have never exercised regularly.","slide":42,"shape":"16","bookPage":"107"},{"text":"2 What is more important than lifestyle for a long healthy life? Having good genes is most important.","slide":42,"shape":"17","bookPage":"107"},{"text":"Speaker\nNotes\nSpeaker A\nMany people believe eating only healthy food / exercising = a long life.BUT: having the (1) wrong genes can make life shorter.Happiness better than always being in (2) the gym.","slide":47,"shape":"15","bookPage":"107"},{"text":"Speaker\nNotes\nSpeaker B\nDon't focus on healthy eating / exercise.Example: grandfather died at (3) 95 and never ate vegetables / exercised.Genes are more important for a long life than (4) lifestyle.Exercise is good but (5) fitness shouldn't be main focus in life.","slide":48,"shape":"14","bookPage":"107"},{"text":"Speaker\nNotes\nSpeaker C\nPrefers good diet and exercise.People only know if they have good genes when they (6) get sick.Therefore, don't take risks.Unhealthy people get the (7) flu or (8) cold more easily.Unhealthy habits increase possibility of a (9) serious illness.","slide":49,"shape":"14","bookPage":"107"},{"text":"Speaker\nNotes\nSpeaker D\nChildren often overweight — eating too much junk food.Some people can live (10) to be 100 despite their unhealthy habits.Prefers to (11) be careful and take care of themself.","slide":50,"shape":"14","bookPage":"107"},{"text":"8 Listen to the extracts. Then discuss the questions with your partner. Speaker 1: “I think it’s great news!” Is the attitude positive or negative? What tells you the attitude?The attitude is positive. “Great” and the up-and-down intonation support the positive attitude.","slide":61,"shape":"16","bookPage":"109"},{"text":"8 Listen to the extracts. Then discuss the questions with your partner. Speaker 2: “Oh, that’s great.” Is the attitude positive or negative? What tells you the attitude?The attitude is negative. The falling, sarcastic intonation reverses the normally positive meaning of “great”.","slide":61,"shape":"17","bookPage":"109"},{"text":"8 Listen to the extracts. Then discuss the questions with your partner. Speaker 3: “What’s wrong with being healthy?” Is the attitude positive or negative? What tells you the attitude?The attitude is positive. The rhetorical question is spoken with a positive intonation; it defends being healthy.","slide":62,"shape":"19","bookPage":"109"},{"text":"8 Listen to the extracts. Then discuss the questions with your partner. Speaker 4: “So now we should all eat fast food and stop exercising?” Is the attitude positive or negative? What tells you the attitude?The attitude is negative. The rhetorical question challenges the idea; the voice is mostly down, then rises at the end.","slide":62,"shape":"20","bookPage":"109"},{"text":"8 Listen to the extracts. Then discuss the questions with your partner. Speaker 5: “I’d say that it’s always better to have a healthy lifestyle.” Is the attitude positive or negative? What tells you the attitude?The attitude is positive. “Better” and the up-and-down intonation support the positive attitude, less strongly than Speaker 1.","slide":63,"shape":"19","bookPage":"109"},{"text":"11. What observation introduces the argument about long life?\nA. Some very old people did not follow healthy routines.\nB. Most very old people began regular exercise late in life.\nC. People with healthy diets usually avoided the studies.","slide":66,"shape":"5","bookPage":null},{"text":"12. Why does speaker A welcome the research?\nA. It promises better results from strict eating rules.\nB. It offers him a new exercise routine to follow.\nC. It supports his preference for enjoying life.","slide":67,"shape":"5","bookPage":null},{"text":"1 Before you listen, discuss the best definition for each word in bold. I don’t feel like going to the gym this afternoon. I just want to stay at home, relax and watch a film. a to sleep until later than usual b to enjoy your favourite hobby c to become less tense or worriedc — to become less tense or worried","slide":86,"shape":"15","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. Marcus is feeling a lot of stress at work. It’s giving him headaches. a worry caused by a difficult situation b an illness caused by not getting enough sleep c pains that come when something unexpected happensa — worry caused by a difficult situation","slide":86,"shape":"16","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. Drinking a lot of water can be a good treatment for a stomachache. a a solution to a problem b a way to cure an illness or injury c something you can drinkb — a way to cure an illness or injury","slide":87,"shape":"18","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. If you reduce the number of calories you eat, you will lose weight. a to count the amount of something b to make something less in size, amount, etc. c to make something larger in size, amount, etc.b — to make something less in size, amount, etc.","slide":87,"shape":"19","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. Exercise has a number of mental benefits, like improving your memory. a relating to the mind b relating to movement c relating to happinessa — relating to the mind","slide":88,"shape":"18","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. Eating healthy food can improve your athletic performance. It makes your muscles and bones stronger and helps you stay healthy. a how often a person does an activity b how well a person does an activity c how easily a person can do an activityb — how well a person does an activity","slide":88,"shape":"19","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. Writing requires a lot of concentration. It’s a good idea to be alone in a quiet room when you’re writing. a the energy required to do something on your own b the ability to stay calm for long periods of time c the ability to give your whole attention to one thingc — the ability to give your whole attention to one thing","slide":89,"shape":"18","bookPage":"114"},{"text":"1 Before you listen, discuss the best definition for each word in bold. Anybody can participate in the game. You don’t need to be an experienced player to join. a to be involved in an activity b to do something well c to improve quickly at somethinga — to be involved in an activity","slide":89,"shape":"19","bookPage":"114"},{"text":"2 Work with a partner. Look at the photos. What do you think are the benefits — if any — of taekwondo? Discuss your ideas.It may help people stay active and develop confidence.","slide":92,"shape":"17","bookPage":"115"},{"text":"2 Work with a partner. Look at the photos. What do you think are the benefits — if any — of team sports? Discuss your ideas.They can provide opportunities to meet people with similar interests.","slide":92,"shape":"18","bookPage":"115"},{"text":"2 Work with a partner. Look at the photos. What do you think are the benefits — if any — of cycling? Discuss your ideas.A cycling trip combines physical activity with seeing new places.","slide":92,"shape":"19","bookPage":"115"},{"text":"2 Work with a partner. Look at the photos. What do you think are the benefits — if any — of acupuncture? Discuss your ideas.It is a traditional treatment; I would want to know more about its claimed benefits.","slide":93,"shape":"17","bookPage":"115"},{"text":"3 Listen to the four presentations. What is Presentation 1 describing? a cycling tour acupuncture a football club taekwondoPresentation 1: Taekwondo.","slide":95,"shape":"15","bookPage":"116"},{"text":"3 Listen to the four presentations. What is Presentation 2 describing? a cycling tour acupuncture a football club taekwondoPresentation 2: A football club.","slide":95,"shape":"16","bookPage":"116"},{"text":"3 Listen to the four presentations. What is Presentation 3 describing? a cycling tour acupuncture a football club taekwondoPresentation 3: A cycling tour.","slide":95,"shape":"17","bookPage":"116"},{"text":"3 Listen to the four presentations. What is Presentation 4 describing? a cycling tour acupuncture a football club taekwondoPresentation 4: Acupuncture.","slide":96,"shape":"16","bookPage":"116"},{"text":"4 Listen again. What are the benefits of Programme 1, taekwondo? Take notes.Taekwondo improves health and well-being, improves concentration, makes you feel good about yourself, improves confidence, and reduces stress.","slide":98,"shape":"15","bookPage":"116"},{"text":"4 Listen again. What are the benefits of Programme 2, football? Take notes.Football improves social life, intellectual performance, physical fitness and team-building skills.","slide":98,"shape":"16","bookPage":"116"},{"text":"4 Listen again. What are the benefits of Programme 3, cycling? Take notes.Cycling provides exercise and a fascinating cultural experience, and improves memory and thinking skills.","slide":98,"shape":"17","bookPage":"116"},{"text":"4 Listen again. What are the benefits of Programme 4, acupuncture? Take notes.Acupuncture reduces pain and helps people lose weight.","slide":99,"shape":"16","bookPage":"116"},{"text":"Benefits of the health programmes\nYour notes\nProgramme 1\nImproves health and well-being; improves concentration; makes you feel good about yourself; improves confidence; reduces stress.\nProgramme 2\nImproves social life, intellectual performance, physical fitness and team-building skills.\nProgramme 3\nProvides exercise and a fascinating cultural experience; improves memory and thinking skills.\nProgramme 4\nReduces pain and helps people lose weight.","slide":100,"shape":"15","bookPage":"116"},{"text":"If you want to lose weight, you should cut down on fatty foods.","slide":105,"shape":"14","bookPage":"111"},{"text":"Last winter, I came down with four colds. I hope I’m healthier this year!","slide":105,"shape":"15","bookPage":"111"},{"text":"I want to try something new. Maybe I’ll take up tennis.","slide":105,"shape":"16","bookPage":"111"},{"text":"Tim is going to try out for the football team. I don’t think he’ll make it, though — he’s not a great player.","slide":106,"shape":"18","bookPage":"111"},{"text":"No matter how good their genes are, these children will not be able to enjoy a long and happy life unless they give up crisps, chocolate bars and sugary drinks.","slide":106,"shape":"19","bookPage":"111"},{"text":"Why don’t you sign up for a yoga class? Yoga is good exercise and it helps you relax.","slide":107,"shape":"17","bookPage":"111"},{"text":"Would you like to join in the game? You can be on our team.","slide":107,"shape":"18","bookPage":"111"},{"text":"It took me a long time to get over the flu. I was ill for two weeks.","slide":107,"shape":"19","bookPage":"111"},{"text":"come down with — to get an illness, especially one which is not serious","slide":119,"shape":"15","bookPage":"112"},{"text":"give up — to stop a habit, often because it is unhealthy","slide":119,"shape":"16","bookPage":"112"},{"text":"sign up for — to agree to become involved in an organized activity","slide":119,"shape":"17","bookPage":"112"},{"text":"join in — to become involved in an activity with other people","slide":119,"shape":"5","bookPage":"112"},{"text":"try out for — to compete for a position on a sports team or a part in a play","slide":120,"shape":"18","bookPage":"112"},{"text":"get over — to become healthy again after having an illness","slide":120,"shape":"19","bookPage":"112"},{"text":"take up — to start doing a particular job or activity","slide":120,"shape":"20","bookPage":"112"},{"text":"cut down on — to eat or drink less of something","slide":121,"shape":"19","bookPage":"112"},{"text":"Have you ever had a cold or the flu? How long did it take you to get over it?","slide":123,"shape":"18","bookPage":"112"},{"text":"Have you ever given a bad habit up, like buying things you don’t need?","slide":123,"shape":"19","bookPage":"112"},{"text":"4 Have you ever signed up for a team?","slide":124,"shape":"17","bookPage":"112"},{"text":"Have you taken any activities up in the past few years?","slide":124,"shape":"19","bookPage":"112"},{"text":"Are there any foods which you want to cut down on?","slide":124,"shape":"5","bookPage":"112"},{"text":"4 Write a follow-up question for each of the questions in Exercise 3. “Have you ever signed up for exercise classes or for a gym membership?”What did you sign up for?","slide":127,"shape":"20","bookPage":"112"},{"text":"4 Write a follow-up question for each of the questions in Exercise 3. “Have you ever had a cold or the flu? How long did it take you to get over it?”Did you get a cold again soon afterwards?","slide":127,"shape":"21","bookPage":"112"},{"text":"4 Write a follow-up question for each of the questions in Exercise 3. “Have you ever given a bad habit up, like buying things you don’t need?”What did you give up?","slide":127,"shape":"22","bookPage":"112"},{"text":"4 Write a follow-up question for each of the questions in Exercise 3. “Have you ever signed up for a team?”What team did you sign up for?","slide":128,"shape":"20","bookPage":"112"},{"text":"4 Write a follow-up question for each of the questions in Exercise 3. “Have you taken any activities up in the past few years?”What activities did you take up?","slide":128,"shape":"21","bookPage":"112"},{"text":"4 Write a follow-up question for each of the questions in Exercise 3. “Are there any foods which you want to cut down on?”Why do you want to eat less of these foods?","slide":128,"shape":"22","bookPage":"112"},{"text":"5 Work with a partner. Answer the questions in Exercise 3. Ask your follow-up questions to find out more information. A: Have you ever signed up for exercise classes or for a gym membership? B: Yes, I have. A: What did you sign up for?B: I actually signed up for exercise classes at a gym, so both!","slide":132,"shape":"14","bookPage":"112"},{"text":"5 Work with a partner. Answer the questions in Exercise 3. Ask your follow-up questions to find out more information. Use get over, then ask for more information.A: How long did it take you to get over the flu?B: About a week.A: Did you get ill again soon afterwards?B: No, I stayed healthy.","slide":132,"shape":"15","bookPage":"112"},{"text":"5 Work with a partner. Answer the questions in Exercise 3. Ask your follow-up questions to find out more information. Use the present perfect for the experience, then the past simple for details.A: Have you taken any activities up recently?B: Yes, I have.A: What did you take up?B: I started running last year.","slide":133,"shape":"17","bookPage":"112"},{"text":"5 Work with a partner. Answer the questions in Exercise 3. Ask your follow-up questions to find out more information. Develop the answer with a relevant follow-up.A: Are there any foods you want to cut down on?B: Yes, takeaway pizza.A: How often do you eat it?B: Two or three times a week.","slide":134,"shape":"17","bookPage":"112"},{"text":"1  Does exercising have emotional benefits? For example, can it make you happier and\ncalmer?","slide":145,"shape":"7","bookPage":"113"},{"text":"2  What's the best way to find new people to go out with and improve your social life?","slide":145,"shape":"8","bookPage":"113"},{"text":"3  Would you describe somebody as ‘intellectual’ if they enjoyed talking about literature\nand philosophy? Why / Why not?","slide":145,"shape":"9","bookPage":"113"},{"text":"4  Which is better for learning a language quickly: hiring a personal tutor or studying in a\nclass? Why?","slide":145,"shape":"10","bookPage":"113"},{"text":"6 When somebody moves to a new country, how long should it take for them to get used to the cultural differences?","slide":146,"shape":"17","bookPage":"113"},{"text":"7 People often think that travelling has educational benefits, but what do people learn?","slide":146,"shape":"18","bookPage":"113"},{"text":"1 Does exercising have emotional benefits? For example, can it make you happier and calmer?Possible answer: Exercise helps me forget stressful things for a while.","slide":146,"shape":"19","bookPage":"113"},{"text":"2 What's the best way to find new people to go out with and improve your social life?Possible answer: Joining an activity club can help me meet people with similar interests.","slide":147,"shape":"16","bookPage":"113"},{"text":"3 Would you describe somebody as ‘intellectual’ if they enjoyed talking about literature and philosophy? Why / Why not?Possible answer: Yes. I would also use intellectual for somebody who enjoys explaining scientific ideas.","slide":147,"shape":"17","bookPage":"113"},{"text":"4 Which is better for learning a language quickly: hiring a personal tutor or studying in a class? Why?Possible answer: A personal tutor can focus on my needs, while a class gives me more people to practise with.","slide":148,"shape":"16","bookPage":"113"},{"text":"5 Which physical activity is best for helping your body stay strong and healthy?Possible answer: I enjoy swimming because it involves much of the body.","slide":148,"shape":"17","bookPage":"113"},{"text":"6 When somebody moves to a new country, how long should it take for them to get used to the cultural differences?Possible answer: It depends on the person and the situation; I would not set the same deadline for everyone.","slide":148,"shape":"18","bookPage":"113"},{"text":"7 People often think that travelling has educational benefits, but what do people learn?Possible answer: People may learn a language, different customs or practical skills such as using an airport.","slide":149,"shape":"19","bookPage":"113"},{"text":"I have taken up swimming at school. I go once a week with two friends. We practise in the shallow pool. I enjoy being active with them.","slide":153,"shape":"6","bookPage":null},{"text":"I have given up buying sweets every day. I now bring fruit for my break. The new habit is simple. I feel proud that I have kept it.","slide":153,"shape":"9","bookPage":null},{"text":"11. How is the importance of genes presented in the introduction?\nA. As a lifestyle change the host has personally tested.\nB. As a finding that rules out exceptions in every case.\nC. As a conclusion many people draw from the reported studies.","slide":159,"shape":"5","bookPage":null},{"text":"12. What role does the example of pizza with friends play?\nA. It makes the speaker’s preference for enjoyment concrete.\nB. It shows how he balances two equally demanding workouts.\nC. It identifies the diet followed by the research participants.","slide":160,"shape":"5","bookPage":null},{"text":"1. The host says four people were asked for their reactions to the research.\nAnswer: TRUE","slide":163,"shape":"5","bookPage":null},{"text":"2. Speaker A is pleased by the research because it fits his preference for enjoying life.\nAnswer: TRUE","slide":163,"shape":"8","bookPage":null},{"text":"I have joined a cycling club. We meet in the park on Saturday mornings. My cousin rides with me. I enjoy it because we can explore new paths together.","slide":168,"shape":"6","bookPage":null},{"text":"I have cut down on fizzy drinks. I take water to school instead. I changed this habit because buying a drink every day cost too much. Now I spend less money at the school shop.","slide":169,"shape":"6","bookPage":null},{"text":"Improves health and\nwell-being","slide":174,"shape":"12","bookPage":"117"},{"text":"Improves concentration","slide":174,"shape":"14","bookPage":"117"},{"text":"Makes you feel good\nabout yourself","slide":174,"shape":"16","bookPage":"117"},{"text":"Improves confidence","slide":174,"shape":"18","bookPage":"117"},{"text":"Reduces stress","slide":174,"shape":"20","bookPage":"117"},{"text":"Swimming in open water\n(sea, river, lake, etc.)","slide":176,"shape":"11","bookPage":"118"},{"text":"Walking in nature club","slide":176,"shape":"13","bookPage":"118"},{"text":"Tree-climbing","slide":176,"shape":"15","bookPage":"118"},{"text":"Cookery classes\n(making healthy food)","slide":176,"shape":"17","bookPage":"118"},{"text":"3 Look at the health programmes you brainstormed in Exercise 2. Which has the most health benefits? Which has the fewest? Why?I would compare physical activity, social contact, learning opportunities and how practical each programme is for our group.","slide":179,"shape":"17","bookPage":"118"},{"text":"3 Choose one programme and write it in the centre of the ideas map below.I would choose a walking club because it could combine activity, time outdoors and conversation with other students.","slide":179,"shape":"18","bookPage":"118"},{"text":"Regular physical\nactivity","slide":180,"shape":"12","bookPage":"118"},{"text":"Time to talk with\nclassmates","slide":180,"shape":"14","bookPage":"118"},{"text":"A break from sitting","slide":180,"shape":"16","bookPage":"118"},{"text":"Explore nearby places","slide":180,"shape":"18","bookPage":"118"},{"text":"A simple shared\nroutine","slide":180,"shape":"20","bookPage":"118"},{"text":"1 Work with a partner. Read the script below for a presentation about a programme and answer the questions. Why does the script begin with rhetorical questions?It begins with rhetorical questions to engage the audience and make them think about the topic. The opening invites listeners to recognize problems in their own lives.","slide":184,"shape":"16","bookPage":"119"},{"text":"1 Why are all the rhetorical questions yes/no questions about you?They make listeners think about their own problems; people who answer yes are ready to hear a solution. The pronoun you addresses the audience directly.","slide":184,"shape":"17","bookPage":"119"},{"text":"1 What three problems do the questions introduce?Difficulty focusing on work; feeling stressed; wanting more exercise while trying something new.","slide":185,"shape":"15","bookPage":"119"},{"text":"1 What is the solution to the problems?Taking up taekwondo. “If so, it’s time to take up taekwondo!” introduces the solution.","slide":185,"shape":"16","bookPage":"119"},{"text":"1 What is the purpose of the part of the script that begins “And as we all know”?It persuades the audience by presenting the benefit of exercise as common knowledge. “And as we all know” makes the claim sound generally accepted; the phrase itself is not evidence.","slide":185,"shape":"17","bookPage":"119"},{"text":"1 What does the script say the programme is good for?Physical well-being, improved concentration, feeling good about yourself, increased confidence and less stress.","slide":186,"shape":"19","bookPage":"119"},{"text":"1 What information does the last part of the script provide?A free introductory class starts on January 15th.","slide":186,"shape":"20","bookPage":"119"},{"text":"4 specific information about the place, time, etc.","slide":190,"shape":"6","bookPage":"119"},{"text":"3 background information about the programme","slide":190,"shape":"7","bookPage":"119"},{"text":"2 introduction of the solution","slide":190,"shape":"9","bookPage":"119"},{"text":"Sign up now for a free introductory class, starting on January 15th.","slide":192,"shape":"15","bookPage":"120"},{"text":"If you’re interested in learning more about our group, check out our website at www.footballsundays.cup.com.","slide":192,"shape":"16","bookPage":"120"},{"text":"This spring, join our six-month course in acupuncture.","slide":193,"shape":"15","bookPage":"120"},{"text":"Learn more about the course and visit us on our open days on the first Saturday of every month.","slide":193,"shape":"16","bookPage":"120"},{"text":"4 Work with a partner and answer the questions. What effect do the imperatives have on the listener?They encourage the listener to take action. An imperative directly tells or invites somebody to do something.","slide":195,"shape":"15","bookPage":"120"},{"text":"4 Work with a partner and answer the questions. Why are imperatives used in the presentations?The presenters want to persuade listeners to sign up for a course, join a group or find out more.","slide":195,"shape":"16","bookPage":"120"},{"text":"5 Work with a partner. Take turns reading the sentences. Your partner listens and rephrases it more persuasively. It is possible to buy one and get one free.Buy one and get one free.","slide":198,"shape":"19","bookPage":"120"},{"text":"5 Work with a partner. Take turns reading the sentences. Your partner listens and rephrases it more persuasively. You should hurry and purchase a ticket now.Hurry and purchase a ticket now.","slide":198,"shape":"20","bookPage":"120"},{"text":"5 Work with a partner. Take turns reading the sentences. Your partner listens and rephrases it more persuasively. People must not forget that our shops are open on Sundays.Don’t forget that our shops are open on Sundays.","slide":198,"shape":"21","bookPage":"120"},{"text":"5 Work with a partner. Take turns reading the sentences. Your partner listens and rephrases it more persuasively. If you would like to register for our course, you should do this before it’s too late!Make sure you register for our course before it’s too late!","slide":199,"shape":"19","bookPage":"120"},{"text":"5 Work with a partner. Take turns reading the sentences. Your partner listens and rephrases it more persuasively. Our running club is a great club for you to come along and join. It’s fun, friendly and free.Come along and join our fun, friendly and free running club.","slide":199,"shape":"20","bookPage":"120"},{"text":"5 Work with a partner. Take turns reading the sentences. Your partner listens and rephrases it more persuasively. We predict you will become happier and healthier by cooking with our recipes.Become healthier and happier by cooking with our recipes.","slide":200,"shape":"19","bookPage":"120"},{"text":"Do you want to get more exercise while trying something new and exciting?","slide":202,"shape":"14","bookPage":"121"},{"text":"Would you like to improve your social life, your intellectual performance, your physical fitness and your team-building skills?","slide":202,"shape":"15","bookPage":"121"},{"text":"Not only does this trip provide terrific exercise and a fascinating cultural experience, it’s the best way to learn.","slide":202,"shape":"16","bookPage":"121"},{"text":"Are you interested in alternative treatments?","slide":203,"shape":"18","bookPage":"121"},{"text":"Have you ever wanted to explore the secrets of traditional Chinese medicine?","slide":203,"shape":"19","bookPage":"121"},{"text":"7 Work with a partner and answer the questions. Do the adjectives in Exercise 6 have a positive or a negative meaning?They are used to create a mainly positive impression. Some, such as cultural, Chinese and alternative, describe a type rather than being positive by themselves.","slide":207,"shape":"19","bookPage":"121"},{"text":"7 What images come to mind when you hear these adjectives?Exciting may suggest trying something new; social may suggest people enjoying an activity together. Different listeners may imagine different things.","slide":207,"shape":"20","bookPage":"121"},{"text":"7 Think of other adjectives you often hear in advertisements and persuasive presentations.Amazing, convenient, interesting, friendly and delicious can help build a positive description.","slide":208,"shape":"19","bookPage":"121"},{"text":"It's a great offer.","slide":209,"shape":"7","bookPage":"121"},{"text":"They're excellent value!","slide":209,"shape":"10","bookPage":"121"},{"text":"It's so convenient.","slide":209,"shape":"13","bookPage":"121"},{"text":"Your Saturdays will become more interesting if you do.","slide":210,"shape":"7","bookPage":"121"},{"text":"It will be incredible for your fitness.","slide":210,"shape":"10","bookPage":"121"},{"text":"They're all delicious.","slide":210,"shape":"13","bookPage":"121"},{"text":"6 Work in small groups. Take turns practising your presentations. Take notes on your classmates’ presentations and feed back to them on how persuasive it was.Your opening questions introduced the problem clearly, and I could see how your programme responds to it.","slide":223,"shape":"20","bookPage":"122"},{"text":"6 Work in small groups. Take turns practising your presentations. Take notes on your classmates’ presentations and feed back to them on how persuasive it was.Sign up gives a clear action, and friendly makes the club sound welcoming.","slide":223,"shape":"21","bookPage":"122"},{"text":"6 Work in small groups. Take turns practising your presentations. Take notes on your classmates’ presentations and feed back to them on how persuasive it was.Please add the meeting place and cost, and explain the reason for your strongest claim.","slide":224,"shape":"20","bookPage":"122"},{"text":"Do you spend most of your day sitting at a desk? Would you like a simple way to meet other students and do something active? Then sign up for our friendly Campus Walking Club!","slide":227,"shape":"13","bookPage":"122"},{"text":"Most people think that exercise means going to a gym, but our programme starts with an ordinary walk. Join us for a relaxed walk around campus and enjoy a break from your desk. You can talk with classmates, explore nearby places and make activity part of your week.","slide":228,"shape":"14","bookPage":"122"},{"text":"The club is run by a small group of students who wanted more social time outdoors. We take a different route each week and choose a comfortable pace together. There is no question that making time for a shared activity takes planning, so a regular meeting time can help.","slide":229,"shape":"14","bookPage":"122"},{"text":"Our first walk starts outside the library at four o'clock next Wednesday. It lasts about thirty minutes and is free. Wear comfortable shoes, bring some water and check the weather before you come. If the weather is unsuitable, we will tell everyone about a new time.","slide":230,"shape":"14","bookPage":"122"},{"text":"You do not need to be an experienced walker to ask about the club. Come along, meet the group and decide whether the route suits you. Take up a simple shared activity and join in the conversation!","slide":231,"shape":"13","bookPage":"122"},{"text":"Problems: too much sitting and wanting to meet people. Solution: a walking club.\nBackground: a student group. Details: place, day, time, duration and cost.","slide":232,"shape":"7","bookPage":"122"},{"text":"Sign up for, take up and join in.","slide":232,"shape":"10","bookPage":"122"},{"text":"Friendly, relaxed and social; Join us, Wear, bring and check.","slide":233,"shape":"7","bookPage":"122"},{"text":"Most people think that … and There is no question that …","slide":233,"shape":"10","bookPage":"122"},{"text":"Use your own programme and accurate details. Revise it using the checklist and\nyour classmates' feedback.","slide":233,"shape":"13","bookPage":"122"},{"text":"Some students want an activity with friends. I suggest a walk around the playground. It could begin ten minutes after class. Teachers could share the meeting time. This gives students a simple social option.","slide":237,"shape":"6","bookPage":null},{"text":"Many students wait quietly before the next lesson. A short walking break could help. Classes could walk once around the building. The route is easy to follow. This is a simple way to use the time.","slide":237,"shape":"9","bookPage":null}];
